@triton.jit
def _vec_t_200000000(pos_ptr, cell_ptr, bat_ptr, s_ptr, a, b, e, m, HAS_CELL: tl.constexpr, pos_ptr_t):
    """Tangent of ``_vec`` along the arguments pos_ptr."""
    x = tl.load(pos_ptr + b * 3, mask=m, other=0.0) - tl.load(pos_ptr + a * 3, mask=m, other=0.0)
    x_t = tl.load(pos_ptr_t + b * 3, mask=m, other=0.0) - tl.load(pos_ptr_t + a * 3, mask=m, other=0.0)
    y = tl.load(pos_ptr + b * 3 + 1, mask=m, other=0.0) - tl.load(pos_ptr + a * 3 + 1, mask=m, other=0.0)
    y_t = tl.load(pos_ptr_t + b * 3 + 1, mask=m, other=0.0) - tl.load(pos_ptr_t + a * 3 + 1, mask=m, other=0.0)
    z = tl.load(pos_ptr + b * 3 + 2, mask=m, other=0.0) - tl.load(pos_ptr + a * 3 + 2, mask=m, other=0.0)
    z_t = tl.load(pos_ptr_t + b * 3 + 2, mask=m, other=0.0) - tl.load(pos_ptr_t + a * 3 + 2, mask=m, other=0.0)
    if HAS_CELL:
        s0 = tl.load(s_ptr + e * 3, mask=m, other=0.0)
        s1 = tl.load(s_ptr + e * 3 + 1, mask=m, other=0.0)
        s2 = tl.load(s_ptr + e * 3 + 2, mask=m, other=0.0)
        if HAS_CELL == 2:
            x += s0 * tl.load(cell_ptr) + s1 * tl.load(cell_ptr + 3) + s2 * tl.load(cell_ptr + 6)
            y += s0 * tl.load(cell_ptr + 1) + s1 * tl.load(cell_ptr + 4) + s2 * tl.load(cell_ptr + 7)
            z += s0 * tl.load(cell_ptr + 2) + s1 * tl.load(cell_ptr + 5) + s2 * tl.load(cell_ptr + 8)
        else:
            c = tl.load(bat_ptr + a, mask=m, other=0).to(tl.int64) * 9
            x += s0 * tl.load(cell_ptr + c, mask=m, other=0.0) + s1 * tl.load(cell_ptr + c + 3, mask=m, other=0.0) + s2 * tl.load(cell_ptr + c + 6, mask=m, other=0.0)
            y += s0 * tl.load(cell_ptr + c + 1, mask=m, other=0.0) + s1 * tl.load(cell_ptr + c + 4, mask=m, other=0.0) + s2 * tl.load(cell_ptr + c + 7, mask=m, other=0.0)
            z += s0 * tl.load(cell_ptr + c + 2, mask=m, other=0.0) + s1 * tl.load(cell_ptr + c + 5, mask=m, other=0.0) + s2 * tl.load(cell_ptr + c + 8, mask=m, other=0.0)
