@triton.jit
def _taper_t_10(r, rc, r_t):
    """Tangent of ``_taper`` along the arguments r."""
    x = r / rc
    x_t = r_t / rc
    x2 = x * x
    x2_t = x_t * x + x * x_t
    x4 = x2 * x2
    x4_t = x2_t * x2 + x2 * x2_t
    return (1.0 + x4 * (-35.0 + x * (84.0 + x * (-70.0 + 20.0 * x))), x4_t * (-35.0 + x * (84.0 + x * (-70.0 + 20.0 * x))) + x4 * (x_t * (84.0 + x * (-70.0 + 20.0 * x)) + x * (x_t * (-70.0 + 20.0 * x) + x * (20.0 * x_t))))


@triton.jit
def _pow_t_10(a, b, a_t):
    """Tangent of ``_pow`` along the arguments a."""
    return (tl.exp(b * tl.log(a)), tl.exp(b * tl.log(a)) * (b * (a_t / a)))


@triton.jit
def _nb_pair_t_00020002200000000(src_ptr, dst_ptr, sh_ptr, pos_ptr, cell_ptr, bat_ptr, t_ptr, q_ptr, tab_ptr, sc_ptr, e, m0, n_types, DT: tl.constexpr, HAS_CELL: tl.constexpr, SHIELD: tl.constexpr, WALL: tl.constexpr, pos_ptr_t, q_ptr_t, tab_ptr_t):
    """Tangent of ``_nb_pair`` along the arguments pos_ptr, q_ptr, tab_ptr."""
    i = tl.load(src_ptr + e, mask=m0, other=0).to(tl.int64)
    k = tl.load(dst_ptr + e, mask=m0, other=0).to(tl.int64)
    m = m0 & (i <= k)
